 static String jsonValue(Object v){if(v==null)return "null";if(v instanceof String)return JSONObject.quote((String)v);return v.toString();}
 void reply(String id,Object value,String error){runOnUiThread(()->web.evaluateJavascript("window.nativeResult("+JSONObject.quote(id)+","+(value==null?"null":jsonValue(value))+","+(error==null?"null":JSONObject.quote(error))+")",null));}
 void event(String kind,Object data){runOnUiThread(()->web.evaluateJavascript("window.nativeEvent&&window.nativeEvent("+JSONObject.quote(kind)+","+jsonValue(data)+")",null));}
 class Bridge {
 @JavascriptInterface public void call(String id,String action,String raw){pool.execute(()->{try{JSONObject p=new JSONObject(raw);Object result;
 switch(action){
 case "widgetPreview":runOnUiThread(()->startActivity(new Intent(MainActivity.this,CustomWidgetActivity.class).putExtra("html",p.optString("html")).putExtra("css",p.optString("css")).putExtra("js",p.optString("js"))));result=true;break;
 case "peerStart":peer.start(p.getString("code"),p.optInt("port",49494),message->event("peerMessage",message));result=true;break;
 case "peerStop":peer.stop();result=true;break;
 case "peerSend":result=peer.send(p.getString("host"),p.optInt("port",49494),p.getString("text"),p.optString("name","Друг"));break;
 case "importWorkspace":importId=id;runOnUiThread(()->startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("application/json").addCategory(Intent.CATEGORY_OPENABLE),23));return;
 case "initialPage":result=getIntent().getStringExtra("page");break;
 case "load":result=load();break;
 case "save":save(p);JSONArray diary=p.optJSONArray("diary");String summary="Добавить предметы и оценки";if(diary!=null&&diary.length()>0){JSONObject d=diary.getJSONObject(0);summary=d.optString("subject")+" · каб. "+d.optString("room","—")+" · "+d.optString("grade");}getSharedPreferences("widgets",0).edit().putString("diary",summary).apply();android.appwidget.AppWidgetManager wm=android.appwidget.AppWidgetManager.getInstance(MainActivity.this);new DiaryWidget().onUpdate(MainActivity.this,wm,wm.getAppWidgetIds(new ComponentName(MainActivity.this,DiaryWidget.class)));result=true;break;
 case "http":result=http(p);break;
 case "ssh":result=ssh(p);break;
 case "sshTest":p.put("probe",true);result=ssh(p);break;
 case "network":result=network(p);break;
 case "digest":{byte[] hash=MessageDigest.getInstance(p.optString("algorithm","SHA-256")).digest(p.getString("text").getBytes(StandardCharsets.UTF_8));StringBuilder hex=new StringBuilder();for(byte v:hash)hex.append(String.format("%02x",v&255));result=hex.toString();break;}
 case "qr":{com.google.zxing.common.BitMatrix matrix=new com.google.zxing.MultiFormatWriter().encode(p.getString("text"),com.google.zxing.BarcodeFormat.QR_CODE,600,600);android.graphics.Bitmap bitmap=android.graphics.Bitmap.createBitmap(600,600,android.graphics.Bitmap.Config.ARGB_8888);for(int y=0;y<600;y++)for(int x=0;x<600;x++)bitmap.setPixel(x,y,matrix.get(x,y)?0xff0b1017:0xffffffff);ByteArrayOutputStream bytes=new ByteArrayOutputStream();bitmap.compress(android.graphics.Bitmap.CompressFormat.PNG,100,bytes);bitmap.recycle();result=android.util.Base64.encodeToString(bytes.toByteArray(),2);break;}
 case "export":exportId=id;exportText=p.getString("text");runOnUiThread(()->startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(p.optString("mime","text/plain")).putExtra(Intent.EXTRA_TITLE,p.optString("name","devlens.txt")),22));return;
 case "device":result=device();break;
 case "sensor":runOnUiThread(()->{sensors.unregisterListener(MainActivity.this);if(p.optBoolean("enabled"))for(int type:new int[]{Sensor.TYPE_ACCELEROMETER,Sensor.TYPE_GYROSCOPE,Sensor.TYPE_MAGNETIC_FIELD}){Sensor x=sensors.getDefaultSensor(type);if(x!=null)sensors.registerListener(MainActivity.this,x,SensorManager.SENSOR_DELAY_UI);}});result=true;break;
 case "remind":if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=PackageManager.PERMISSION_GRANTED){runOnUiThread(()->requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},3));throw new Exception("Разрешите уведомления и повторите сохранение");}ReminderReceiver.schedule(MainActivity.this,p);result=true;break;
 case "cancelReminder":ReminderReceiver.cancel(MainActivity.this,p.getInt("id"));result=true;break;
 case "music":Intent i=new Intent(MainActivity.this,MusicService.class).setAction(p.optString("action","play"));i.putExtra("url",p.optString("url"));i.putExtra("title",p.optString("title","DevLens Music"));if(p.has("queue")){i.putExtra("queue",p.getJSONArray("queue").toString());i.putExtra("index",p.optInt("index",0));}startForegroundService(i);result=true;break;
 case "musicStatus":result=MusicService.status();break;
 case "pickMusic":if(pickId!=null)throw new Exception("Выбор файлов уже открыт");pickId=id;runOnUiThread(()->{try{Intent x=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("audio/*").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);x.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(x,20);}catch(Exception e){String pendingId=pickId;pickId=null;reply(pendingId,null,"Не удалось открыть выбор аудио: "+e.getMessage());}});return;
 case "scan":if(checkSelfPermission("android.permission.CAMERA")!=PackageManager.PERMISSION_GRANTED){runOnUiThread(()->requestPermissions(new String[]{"android.permission.CAMERA"},4));throw new Exception("Разрешите камеру и повторите сканирование");}scanId=id;runOnUiThread(()->startActivityForResult(new Intent(MainActivity.this,ScanActivity.class),21));return;
 case "spectrum":if(p.optBoolean("enabled")){if(checkSelfPermission("android.permission.RECORD_AUDIO")!=PackageManager.PERMISSION_GRANTED){runOnUiThread(()->requestPermissions(new String[]{"android.permission.RECORD_AUDIO"},5));throw new Exception("Разрешите микрофон и повторите запуск");}startAudio();}else recording=false;result=true;break;
 case "mock":result=mock(p);break;
 default:throw new Exception("Неизвестный инструмент: "+action);
 }reply(id,result,null);}catch(Exception e){reply(id,null,e.getMessage()==null?e.toString():e.getMessage());}});}
 }
 JSONObject load()throws Exception{String c=getSharedPreferences("vault",0).getString("state","");if(c.isEmpty())return new JSONObject();byte[] all=android.util.Base64.decode(c,0);Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Arrays.copyOfRange(all,0,12)));return new JSONObject(new String(cipher.doFinal(Arrays.copyOfRange(all,12,all.length)),StandardCharsets.UTF_8));}
 void save(JSONObject p)throws Exception{Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key());ByteArrayOutputStream out=new ByteArrayOutputStream();out.write(c.getIV());out.write(c.doFinal(p.toString().getBytes(StandardCharsets.UTF_8)));if(!getSharedPreferences("vault",0).edit().putString("state",android.util.Base64.encodeToString(out.toByteArray(),2)).commit())throw new IOException("Не удалось сохранить настройки");}
 javax.crypto.SecretKey key()throws Exception{KeyStore k=KeyStore.getInstance("AndroidKeyStore");k.load(null);if(!k.containsAlias("devlens")){KeyGenerator g=KeyGenerator.getInstance("AES","AndroidKeyStore");g.init(new KeyGenParameterSpec.Builder("devlens",KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes("GCM").setEncryptionPaddings("NoPadding").build());g.generateKey();}return (javax.crypto.SecretKey)k.getKey("devlens",null);}
 JSONObject http(JSONObject p)throws Exception{URL url=new URL(p.getString("url"));if(!Arrays.asList("http","https").contains(url.getProtocol()))throw new Exception("Только HTTP/HTTPS");HttpURLConnection c=(HttpURLConnection)url.openConnection();c.setConnectTimeout(15000);c.setReadTimeout(Math.min(120000,Math.max(1000,p.optInt("timeout",60000))));c.setInstanceFollowRedirects(false);c.setRequestMethod(p.optString("method","GET"));JSONObject h=p.optJSONObject("headers");if(h!=null)for(Iterator<String>it=h.keys();it.hasNext();){String k=it.next();c.setRequestProperty(k,h.getString(k));}long start=System.currentTimeMillis();try{if(p.has("body")&&!p.optString("body").isEmpty()){c.setDoOutput(true);try(OutputStream o=c.getOutputStream()){o.write(p.getString("body").getBytes(StandardCharsets.UTF_8));}}int code=c.getResponseCode();InputStream in=code>=400?c.getErrorStream():c.getInputStream();String body=in==null?"":read(in,2*1024*1024);JSONObject headers=new JSONObject();for(Map.Entry<String,List<String>> x:c.getHeaderFields().entrySet())if(x.getKey()!=null)headers.put(x.getKey(),String.join(", ",x.getValue()));return new JSONObject().put("status",code).put("body",body).put("headers",headers).put("ms",System.currentTimeMillis()-start);}finally{c.disconnect();}}
 static String read(InputStream in,int limit)throws IOException{ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] buf=new byte[4096];int n;try{while((n=in.read(buf))!=-1){if(b.size()+n>limit){b.write(buf,0,Math.max(0,limit-b.size()));b.write("\n[вывод ограничен]".getBytes(StandardCharsets.UTF_8));break;}b.write(buf,0,n);}}finally{in.close();}return b.toString("UTF-8");}
 JSONObject ssh(JSONObject p)throws Exception{JSch j=new JSch();String identity=p.optString("privateKey");if(!identity.isEmpty())j.addIdentity("devlens",identity.getBytes(StandardCharsets.UTF_8),null,p.optString("passphrase").getBytes(StandardCharsets.UTF_8));Session session=j.getSession(p.getString("user").trim(),p.getString("host").trim(),p.optInt("port",22));session.setPassword(p.optString("password"));String kh=new File(getFilesDir(),"known_hosts").getAbsolutePath();new File(kh).createNewFile();j.setKnownHosts(kh);session.setConfig("StrictHostKeyChecking","ask");session.setConfig("PreferredAuthentications","publickey,password,keyboard-interactive");session.setServerAliveInterval(15000);session.setServerAliveCountMax(2);session.setUserInfo(new UserInfo(){public String getPassphrase(){return p.optString("passphrase");}public String getPassword(){return p.optString("password");}public boolean promptPassword(String x){return !p.optString("password").isEmpty();}public boolean promptPassphrase(String x){return !p.optString("passphrase").isEmpty();}public void showMessage(String m){event("notice",m);}public boolean promptYesNo(String m){CountDownLatch latch=new CountDownLatch(1);boolean[] yes={false};runOnUiThread(()->new AlertDialog.Builder(MainActivity.this).setTitle("SSH: проверка ключа сервера").setMessage(m).setPositiveButton("Доверять",(d,w)->{yes[0]=true;latch.countDown();}).setNegativeButton("Отмена",(d,w)->latch.countDown()).setOnCancelListener(d->latch.countDown()).show());try{latch.await(90,TimeUnit.SECONDS);}catch(Exception e){}return yes[0];}});
 ChannelExec channel=null;try{event("sshStatus","Подключение к "+p.getString("host")+"…");session.connect(20000);event("sshStatus","SSH-аутентификация успешна");if(p.optBoolean("probe"))return new JSONObject().put("connected",true).put("serverVersion",session.getServerVersion()).put("fingerprint",session.getHostKey().getFingerPrint(j));channel=(ChannelExec)session.openChannel("exec");channel.setCommand(p.getString("command"));ByteArrayOutputStream out=new ByteArrayOutputStream();OutputStream capped=new OutputStream(){public synchronized void write(int b){if(out.size()<524288)out.write(b);}public synchronized void write(byte[] b,int o,int l){out.write(b,o,Math.min(l,Math.max(0,524288-out.size())));}};channel.setOutputStream(capped);channel.setErrStream(capped);channel.setInputStream(null);channel.connect(15000);event("sshStatus","Команда выполняется…");long lastOutput=0;int lastSize=0;long end=System.currentTimeMillis()+60000;while(!channel.isClosed()&&System.currentTimeMillis()<end){Thread.sleep(50);if(System.currentTimeMillis()-lastOutput>=250&&out.size()!=lastSize){lastOutput=System.currentTimeMillis();lastSize=out.size();event("sshOutput",out.toString("UTF-8"));}}if(!channel.isClosed())throw new Exception("Команда превысила 60 секунд; SSH-канал закрыт. Процесс на сервере мог продолжить работу.");return new JSONObject().put("output",out.toString("UTF-8")).put("exit",channel.getExitStatus());}catch(JSchException e){String message=e.getMessage()==null?"":e.getMessage();String explanation=message;if(message.contains("Auth fail")||message.contains("Auth cancel"))explanation="Сервер отклонил вход. Проверьте пользователя, пароль/ключ и разрешённые методы входа.";else if(message.contains("Connection refused"))explanation="SSH-порт не принимает соединение. Проверьте порт и запущен ли sshd.";else if(message.toLowerCase(Locale.ROOT).contains("timeout")||message.contains("timed out"))explanation="Сервер не ответил вовремя. Проверьте IP, сеть/VPN и firewall.";else if(message.contains("UnknownHost"))explanation="Не удалось найти хост. Проверьте адрес сервера.";throw new Exception(explanation+"\nSSH: "+message,e);}finally{if(channel!=null)channel.disconnect();session.disconnect();}}
 JSONObject network(JSONObject p)throws Exception{String host=p.getString("host").trim();if(host.isEmpty()||host.contains("/")||host.contains(" "))throw new Exception("Введите имя хоста или IP без протокола");long start=System.currentTimeMillis();JSONArray ips=new JSONArray();for(InetAddress a:InetAddress.getAllByName(host))ips.put(a.getHostAddress());JSONObject result=new JSONObject().put("addresses",ips).put("dnsMs",System.currentTimeMillis()-start);JSONArray ports=new JSONArray();String[] list=p.optString("ports","22,80,443,8080").split(",");if(list.length>32)throw new Exception("Не более 32 портов за проверку");for(String raw:list){int port=Integer.parseInt(raw.trim());if(port<1||port>65535)throw new Exception("Порт должен быть от 1 до 65535");long t=System.currentTimeMillis();JSONObject v=new JSONObject().put("port",port);try(Socket sock=new Socket()){sock.connect(new InetSocketAddress(host,port),1000);v.put("open",true).put("ms",System.currentTimeMillis()-t);}catch(Exception e){v.put("open",false);}ports.put(v);}result.put("ports",ports);if(p.optBoolean("tls")){try(SSLSocket socket=(SSLSocket)SSLSocketFactory.getDefault().createSocket()){socket.connect(new InetSocketAddress(host,443),4000);socket.setSoTimeout(4000);SSLParameters params=socket.getSSLParameters();params.setEndpointIdentificationAlgorithm("HTTPS");socket.setSSLParameters(params);socket.startHandshake();java.security.cert.X509Certificate cert=(java.security.cert.X509Certificate)socket.getSession().getPeerCertificates()[0];result.put("tls",new JSONObject().put("protocol",socket.getSession().getProtocol()).put("subject",cert.getSubjectX500Principal().toString()).put("expires",cert.getNotAfter().toString()));}catch(Exception e){result.put("tlsError",e.getMessage());}}return result;}
 JSONObject device()throws Exception{ActivityManager.MemoryInfo m=new ActivityManager.MemoryInfo();((ActivityManager)getSystemService(ACTIVITY_SERVICE)).getMemoryInfo(m);Intent b=registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));JSONObject o=new JSONObject().put("model",Build.MANUFACTURER+" "+Build.MODEL).put("android",Build.VERSION.RELEASE).put("memoryTotal",m.totalMem).put("memoryFree",m.availMem).put("battery",b==null?-1:b.getIntExtra(BatteryManager.EXTRA_LEVEL,-1));JSONArray ips=new JSONArray();Enumeration<NetworkInterface> it=NetworkInterface.getNetworkInterfaces();if(it!=null)while(it.hasMoreElements()){NetworkInterface n=it.nextElement();Enumeration<InetAddress>a=n.getInetAddresses();while(a.hasMoreElements()){InetAddress addr=a.nextElement();if(!addr.isLoopbackAddress()&&addr instanceof Inet4Address)ips.put(addr.getHostAddress());}}return o.put("ips",ips);}
 @Override public void onSensorChanged(SensorEvent e){if(e.sensor.getType()==Sensor.TYPE_ACCELEROMETER&&System.currentTimeMillis()-lastSensor<75)return;if(e.sensor.getType()==Sensor.TYPE_ACCELEROMETER)lastSensor=System.currentTimeMillis();try{JSONArray v=new JSONArray();for(float x:e.values)v.put((double)x);event("sensor",new JSONObject().put("type",e.sensor.getType()).put("values",v));}catch(Exception ignored){}}
 @Override public void onAccuracyChanged(Sensor s,int a){}
 void startAudio(){if(recording)return;recording=true;pool.execute(()->{try{int size=AudioRecord.getMinBufferSize(16000,AudioFormat.CHANNEL_IN_MONO,AudioFormat.ENCODING_PCM_16BIT);recorder=new AudioRecord(MediaRecorder.AudioSource.MIC,16000,AudioFormat.CHANNEL_IN_MONO,AudioFormat.ENCODING_PCM_16BIT,Math.max(size,4096));recorder.startRecording();short[] buf=new short[1024];while(recording){int n=recorder.read(buf,0,buf.length);if(n<=0)throw new IOException("Нет данных микрофона");JSONArray bands=new JSONArray();double rms=0;for(int a=0;a<n;a++)rms+=buf[a]*(double)buf[a];for(int b=0;b<32;b++){double freq=80*Math.pow(90,b/31.0),re=0,im=0;for(int a=0;a<n;a++){double w=.5-.5*Math.cos(2*Math.PI*a/(n-1));re+=buf[a]*w*Math.cos(2*Math.PI*freq*a/16000);im+=buf[a]*w*Math.sin(2*Math.PI*freq*a/16000);}bands.put(Math.max(0,Math.min(1,(20*Math.log10(Math.max(1,Math.hypot(re,im)/n)/32768)+80)/80)));}event("audio",new JSONObject().put("bands",bands).put("dbfs",20*Math.log10(Math.max(1,Math.sqrt(rms/n))/32768)));}}catch(Exception e){event("notice",e.toString());}finally{recording=false;if(recorder!=null){recorder.release();recorder=null;}}});}
 JSONObject mock(JSONObject p)throws Exception{if(!p.optBoolean("enabled")){if(mock!=null)mock.close();mock=null;return new JSONObject().put("running",false);}if(mock!=null&&!mock.isClosed())throw new Exception("Сначала остановите текущий mock-сервер");mockBody=p.optString("body","{}");mockCode=p.optInt("code",200);mockDelay=Math.min(5000,Math.max(0,p.optInt("delay",0)));int port=p.optInt("port",8787);ServerSocket server=new ServerSocket(port);mock=server;pool.execute(()->{while(!server.isClosed())try{Socket client=server.accept();client.setSoTimeout(3000);try{BufferedReader r=new BufferedReader(new InputStreamReader(client.getInputStream()));String line=r.readLine();int bytes=0;String h;while((h=r.readLine())!=null&&!h.isEmpty()&&(bytes+=h.length())<16384){}Thread.sleep(mockDelay);byte[] body=mockBody.getBytes(StandardCharsets.UTF_8);OutputStream o=client.getOutputStream();o.write(("HTTP/1.1 "+mockCode+" Mock\r\nContent-Type: application/json; charset=utf-8\r\nContent-Length: "+body.length+"\r\nConnection: close\r\n\r\n").getBytes(StandardCharsets.UTF_8));o.write(body);o.flush();event("mock",line);}finally{client.close();}}catch(Exception e){if(!server.isClosed())event("notice",e.toString());}});return new JSONObject().put("running",true).put("port",port);}

 JSONObject importTrack(Uri uri,int flags)throws Exception{
 String name="Аудиофайл";
 try(android.database.Cursor cursor=getContentResolver().query(uri,new String[]{android.provider.OpenableColumns.DISPLAY_NAME},null,null,null)){
 if(cursor!=null&&cursor.moveToFirst())name=cursor.getString(0);
 }
 boolean persisted=false;
 try{getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);persisted=true;}catch(SecurityException ignored){}
 // Some providers grant only temporary access; retain a private copy in that case.
 Uri playable=uri;
 if(!persisted){File directory=new File(getFilesDir(),"music");if(!directory.exists()&&!directory.mkdirs())throw new IOException("Не удалось создать библиотеку музыки");File file=new File(directory,UUID.randomUUID()+".audio");try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(file)){if(in==null)throw new IOException("Файл недоступен");byte[] buffer=new byte[65536];long total=0;int n;while((n=in.read(buffer))!=-1){total+=n;if(total>512L*1024*1024)throw new IOException("Файл превышает 512 МБ: "+name);out.write(buffer,0,n);}}catch(Exception e){file.delete();throw e;}playable=Uri.fromFile(file);}
 else try(android.content.res.AssetFileDescriptor fd=getContentResolver().openAssetFileDescriptor(uri,"r")){if(fd==null)throw new IOException("Нет доступа к файлу: "+name);}
 return new JSONObject().put("url",playable.toString()).put("title",name).put("local",true);
 }
